440	    /// Run one tool. Text by default; `format: json` for structured output.
441	    pub fn call(&mut self, name: &str, args: &Value) -> Result<String> {
442	        let text = |k: &str| text_arg(args, k);
443	        let int = |k: &str| int_arg(args, k);
444	        let json_out = text("format").as_deref() == Some("json");
445	        let memory_tool = matches!(name, "remember" | "recall" | "forget" | "memory_describe");
446	        if memory_tool {
447	            if self.opts.memory.is_none() {
448	                bail!("memory is not enabled on this server (start it with --memory)");
449	            }
450	            if self.memory_tools() == Some(MemoryTools::Recall) && matches!(name, "remember" | "forget") {
451	                bail!("this server exposes memory read-only (--memory-tools recall)");
452	            }
453	        } else if !self.data_enabled()
454	            && matches!(name, "search" | "resolve_group" | "get" | "describe" | "aggregate")
455	        {
456	            bail!("no data index on this server; it serves memory only");
457	        }
458	
459	        match name {
460	            "search" => {
461	                let scope = match text("scope").as_deref() {
462	                    None => None,
463	                    Some("group") => Some(Scope::Group),
464	                    Some("others") => Some(Scope::Others),
465	                    Some("all") => Some(Scope::All),
466	                    Some(other) => bail!("unknown scope {other:?}"),
467	                };
468	                let sort = match text("sort").as_deref() {
469	                    None | Some("relevance") => Sort::Relevance,
470	                    Some("newest") => Sort::Newest,
471	                    Some(other) => bail!("unknown sort {other:?}"),
472	                };
473	                let filters = where_filters(args)?;
474	                let req = SearchRequest {
475	                    group: text("group"),
476	                    query: text("query").unwrap_or_default(),
477	                    scope,
478	                    filters,
479	                    since: text("since"),
480	                    until: text("until"),
481	                    sort,
482	                    limit: int("limit").unwrap_or(5).clamp(1, 25),
483	                    offset: int("offset").unwrap_or(0),
484	                    fallback: true,
485	                };
486	                let outcome = self.store()?.search(&req)?;
487	                Ok(if json_out { serde_json::to_string(&outcome)? } else { render::search(&outcome) })
488	            }
489	            "resolve_group" => {
490	                let query = text("query").ok_or_else(|| anyhow::anyhow!("`query` is required"))?;
491	                let store = self.store()?;
492	                let found = store.resolve(&query, int("limit").unwrap_or(10).clamp(1, 25))?;
493	                let about = &store.config().about;
494	                Ok(if json_out {
495	                    serde_json::to_string(
496	                        &json!({"query": query, "candidates": found, "ambiguous": found.len() > 1}),
497	                    )?
498	                } else {
499	                    render::resolve(&query, &found, &about.record, &about.group)
500	                })
501	            }
502	            "get" => {
503	                let id = text("id").ok_or_else(|| anyhow::anyhow!("`id` is required"))?;
504	                match self.store()?.get(&id)? {
505	                    Some(doc) => Ok(serde_json::to_string(&doc)?),
506	                    None => bail!("no record with id {id:?}"),
507	                }
508	            }
509	            "describe" => {
510	                let d = self.store()?.describe(8)?;
511	                Ok(if json_out { serde_json::to_string(&d)? } else { render::describe(&d) })
512	            }
513	            "aggregate" => {
514	                let metric = match text("metric") {
515	                    None => Metric::Count,
516	                    Some(m) => Metric::parse(&m).ok_or_else(|| {
517	                        anyhow::anyhow!("unknown metric {m:?}; use count, distinct, sum, avg, min or max")
518	                    })?,
519	                };
520	                let req = AggregateRequest {
521	                    query: text("query").unwrap_or_default(),
522	                    group: text("group"),
523	                    group_contains: text("group_contains"),
524	                    filters: where_filters(args)?,
525	                    numeric: list_arg(args, "numeric"),
526	                    since: text("since"),
527	                    until: text("until"),
528	                    by: text("by"),
529	                    metric,
530	                    field: text("field"),
531	                    limit: int("limit").unwrap_or(20),
532	                };
533	                let outcome = self.store()?.aggregate(&req)?;
534	                Ok(if json_out { serde_json::to_string(&outcome)? } else { render::aggregate(&outcome) })
535	            }
536	            "remember" => {
537	                let req = Remember {
538	                    text: text("text")
539	                        .ok_or_else(|| anyhow::anyhow!("`text` is required: the one thing to remember"))?,
540	                    kind: match text("kind") {
541	                        Some(k) => Some(
542	                            Kind::parse(&k)
543	                                .ok_or_else(|| anyhow::anyhow!("unknown kind {k:?}; use {}", Kind::NAMES))?,
544	                        ),
545	                        None => None,
546	                    },
547	                    subject: text("subject"),
548	                    key: text("key"),
549	                    tags: list_arg(args, "tags"),
550	                    importance: int("importance").map(|i| i.min(255) as u8),
551	                    confidence: args.get("confidence").and_then(Value::as_f64),
552	                    source: text("source"),
553	                    refs: list_arg(args, "refs"),
554	                    pinned: bool_arg(args, "pinned"),
555	                    expires: text("expires"),
556	                    aliases: list_arg(args, "aliases"),
557	                    ns: text("ns"),
558	                };
559	                self.ensure_memory()?;
560	                let out = self.memory.as_mut().expect("opened").remember(&req)?;
561	                Ok(if json_out { serde_json::to_string(&out)? } else { out.render() })
562	            }
563	            "recall" => {
564	                let req = RecallRequest {
565	                    query: text("query").unwrap_or_default(),
566	                    ns: text("ns"),
567	                    subject: text("subject"),
568	                    kinds: kinds_arg(args)?,
569	                    since: text("since"),
570	                    until: text("until"),
571	                    as_of: text("as_of"),
572	                    history: bool_arg(args, "history"),
573	                    budget: int("budget"),
574	                    limit: int("limit"),
575	                    with_records: bool_arg(args, "with_records"),
576	                    briefing: text("query").is_none()
577	                        && text("subject").is_none()
578	                        && args.get("kind").is_none(),
579	                };
580	                if req.with_records && self.data_enabled() {
581	                    let _ = self.ensure_store();
582	                }
583	                self.ensure_memory()?;
584	                let store = self.store.as_ref();
585	                let out = self.memory.as_mut().expect("opened").recall(&req, store)?;
586	                Ok(if json_out { serde_json::to_string(&out)? } else { out.render() })
587	            }
588	            "forget" => {
589	                let f = Forget {
590	                    id: text("id"),
591	                    subject: text("subject"),
592	                    key: text("key"),
593	                    ns: text("ns"),
594	                    reason: text("reason"),
595	                };
596	                self.ensure_memory()?;
597	                let m = self.memory.as_mut().expect("opened").forget(&f)?;
598	                Ok(if json_out {
599	                    serde_json::to_string(&m)?
600	                } else {
601	                    format!("forgot {}\n  {}\n", m.id, m.line(&crate::now_rfc3339(), false))
602	                })
603	            }
604	            "memory_describe" => {
605	                self.ensure_memory()?;
606	                let s = self.memory.as_ref().expect("opened").stats()?;
607	                Ok(if json_out { serde_json::to_string(&s)? } else { render::memory_stats(&s) })
608	            }
609	            other => bail!("unknown tool {other:?}"),
610	        }
611	    }
